('X?c nh?n t?i kho?n', 'X?c nh?n t?i kho?n', '<div style="padding: 0 19px">\r\n    <h1>Xin ch?o, {user_name}!</h1>\r\n    <h2>Ch?o m?ng b?n ??n v?i {site_name}!</h2>\r\n\r\n    <p>T?i kho?n {site_name} c?a b?n ?? ???c t?o th?nh c?ng.</p>\r\n    <p>N?n t?ng c?a ch?ng t?i c? nhi?u t?nh n?ng gi?p b?n l?m vi?c nhanh h?n v? hi?u qu? h?n.</p>\r\n    <p>B?n c? th? d?ng {site_name} cho:</p>\r\n    <p>\r\n    <ul>\r\n        <li>Vi?t n?i dung</li>\r\n        <li>T?o ?nh</li>\r\n        <li>Chatbot</li>\r\n        <li>Chuy?n gi?ng n?i th?nh v?n b?n</li>\r\n        <li>L?p tr?nh</li>\r\n    </ul>\r\n    </p>\r\n    <p>C?m ?n b?n ?? ch?n {site_name}. Ch?ng t?i r?t vui ???c ??ng h?nh c?ng b?n.</p>\r\n</div>\r\n\r\n<br>\r\n\r\n<a href="{user_activation_url}" class="btn btn-lg btn-block btn-round">\r\n    X?c nh?n t?i kho?n\r\n</a>\r\n\r\n<p class="need-help-p">C?n h? tr?? <a href="{site_url}">Li?n h? v?i ch?ng t?i.</a></p>', NULL, '2023-06-23 15:34:21'),
('L?i m?i tham gia', 'L?i m?i tham gia', '<div style="padding: 0 19px">\r\n    <h1>B?n ?? nh?n ???c l?i m?i! Ch?c m?ng!</h1>\r\n    <h1>{site_name}</h1>\r\n    <p>Xin ch?o,</p>\r\n    <p>Ch?ng t?i r?t vui ???c m?i b?n tham gia {site_name}. N?n t?ng n?y ???c thi?t k? ?? gi?p doanh nghi?p v? c? nh?n t?n d?ng s?c m?nh AI ?? t?o n?i dung nhanh v? d? d?ng h?n.</p>\r\n    <p>B?n c? th? d?ng {site_name} cho:</p>\r\n    <p>\r\n    <ul>\r\n        <li>Vi?t n?i dung</li>\r\n        <li>T?o ?nh</li>\r\n        <li>Chatbot</li>\r\n        <li>Chuy?n gi?ng n?i th?nh v?n b?n</li>\r\n        <li>L?p tr?nh</li>\r\n    </ul>\r\n    </p>\r\n    <p>Sau khi t?o t?i kho?n, b?n c? th? b?t ??u kh?m ph? n?n t?ng v? tr?i nghi?m nh?ng g? n? mang l?i.</p>\r\n    <p>C?m ?n b?n ?? quan t?m. H?n g?p b?n tr?n {site_name}.</p>\r\n</div>\r\n\r\n<br>\r\n\r\n<a href="{affiliate_url}" class="btn btn-lg btn-block btn-round">\r\n    Kh?m ph? ngay\r\n</a>\r\n\r\n<p class="need-help-p">C?n h? tr?? <a href="{site_url}">Li?n h? v?i ch?ng t?i.</a></p>', NULL, '2023-07-14 17:29:47'),
('??t l?i m?t kh?u', '??t l?i m?t kh?u', '<div style="padding: 0 19px">\r\n    <h1>??t l?i m?t kh?u</h1>\r\n    <p>Xin ch?o,</p>\r\n    <p>Ch?ng t?i v?a nh?n ???c y?u c?u ??t l?i m?t kh?u cho t?i kho?n c?a b?n. ?? b?o m?t, h?y nh?n n?t b?n d??i ?? t?o m?t kh?u m?i.</p>\r\n    <p>Tr?n tr?ng,</p>\r\n    <p>{site_name}</p>\r\n</div>\r\n\r\n<br>\r\n\r\n<a href="{reset_url}" class="btn btn-lg btn-block btn-round">\r\n    ??t l?i m?t kh?u\r\n</a>\r\n\r\n<p class="need-help-p">C?n h? tr?? <a href="{site_url}">Li?n h? v?i ch?ng t?i.</a></p>', NULL, '2023-06-23 15:38:48');
